import{_ as d,o as t,c as o,a8 as c}from"./chunks/framework.BqC7ICod.js";const g=JSON.parse('{"title":"문장","description":"randSentence는 주어와 서술어를 갖춘 완결된 문장을 만듭니다. 이 페이지는 생성기가 무엇을 어디에 세울지 정하는 방식을 설명합니다. 옵션 하나하나는 레퍼런스 페이지에 있습니다.","frontmatter":{},"headers":[],"relativePath":"ko/sentence/index.md","filePath":"ko/sentence/index.md","lastUpdated":1788614611000}'),a={name:"ko/sentence/index.md"};function r(n,e,h,l,i,s){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="문장" tabindex="-1">문장 <a class="header-anchor" href="#문장" aria-label="Permalink to &quot;문장&quot;">​</a></h1><p><a href="./rand-sentence"><code>randSentence</code></a>는 주어와 서술어를 갖춘 완결된 문장을 만듭니다. 이 페이지는 생성기가 무엇을 어디에 세울지 정하는 방식을 설명합니다. 옵션 하나하나는 <a href="./rand-sentence">레퍼런스 페이지</a>에 있습니다.</p><h2 id="the-words-belong-together" tabindex="-1">동사가 정하는 단어 조합 <a class="header-anchor" href="#the-words-belong-together" aria-label="Permalink to &quot;동사가 정하는 단어 조합 {#the-words-belong-together}&quot;">​</a></h2><p>한 문장의 단어를 묶어 주는 것은 동사입니다. 모든 동사는 어떤 종류의 명사가 그 행위를 할 수 있는지, 타동사라면 무엇에 할 수 있는지를 밝혀 두고, 명사는 거기서만 뽑습니다.</p><p>그래서 <code>여우가 사과를 먹는다</code>는 생성기가 만들 수 있는 문장이고 <code>여우가 철학을 먹는다</code>는 아닙니다. <code>먹는다</code>는 먹을 수 있는 것만 받기 때문입니다.</p><p>이를 위해 명사에 따로 붙인 표시는 없습니다. 25개 <a href="./../word/themes">테마</a>가 이미 그 단어가 무엇인지 알려 주므로, 테마마다 <strong>명사 부류</strong>를 하나씩 대응시킵니다. 모든 언어가 같은 대응을 씁니다.</p><table tabindex="0"><thead><tr><th>부류</th><th>테마</th></tr></thead><tbody><tr><td><code>creature</code></td><td><code>animal</code>, <code>myth</code></td></tr><tr><td><code>person</code></td><td><code>job</code></td></tr><tr><td><code>plant</code></td><td><code>plant</code></td></tr><tr><td><code>edible</code></td><td><code>food</code>, <code>drink</code></td></tr><tr><td><code>thing</code></td><td><code>object</code>, <code>tool</code>, <code>clothing</code>, <code>product</code>, <code>gem</code>, <code>music</code></td></tr><tr><td><code>vehicle</code></td><td><code>vehicle</code></td></tr><tr><td><code>place</code></td><td><code>place</code>, <code>nature</code>, <code>space</code></td></tr><tr><td><code>event</code></td><td><code>weather</code>, <code>sport</code>, <code>time</code></td></tr><tr><td><code>idea</code></td><td><code>concept</code>, <code>emotion</code>, <code>finance</code>, <code>tech</code>, <code>color</code></td></tr><tr><td><code>body</code></td><td><code>body</code></td></tr></tbody></table><p><code>creature</code>와 <code>person</code>을 받는 동사는 사자도 자물쇠공도 할 수 있고, 그 밖의 것은 할 수 없습니다. 결과가 빈칸을 채운 틀이 아니라 문장으로 읽히는 것은 이 규칙 하나 덕분입니다.</p><p>그렇다고 모든 문장이 그럴듯한 말이 되지는 않습니다. 여기서 사자는 푸딩을 구울 수 있고 오카리나는 해질녘에 반짝일 수 있습니다. 부류가 막는 것은 애초에 뜻이 통하지 않는 조합입니다.</p><h2 id="the-shapes-belong-to-the-language" tabindex="-1">언어마다 다른 문장 형태 <a class="header-anchor" href="#the-shapes-belong-to-the-language" aria-label="Permalink to &quot;언어마다 다른 문장 형태 {#the-shapes-belong-to-the-language}&quot;">​</a></h2><p>각 언어는 자기 문법이 허용하는 형태를 자기 어순으로 적어 두고, 구마다 필요한 조사나 전치사도 함께 적습니다. 한국어는 동사로 끝나고, 영어는 동사를 두 번째에 두며, 중국어는 행위의 배경을 동사 앞에 둡니다.</p><table tabindex="0"><thead><tr><th>언어</th><th>문장</th></tr></thead><tbody><tr><td>한국어</td><td><code>검은 고양이가 숲에서 잠잔다.</code></td></tr><tr><td>일본어</td><td><code>ハンバーガーが暗礁で冷める。</code></td></tr><tr><td>중국어</td><td><code>巨乌贼又品尝朱红椰汁。</code></td></tr><tr><td>영어</td><td><code>The angler cleans the towel in the ivory balcony.</code></td></tr><tr><td>독일어</td><td><code>Im Frühling blüht eine Chrysantheme noch.</code></td></tr></tbody></table><p>여기서 두 가지가 따라옵니다.</p><p>첫째, 언어는 자기가 올바르게 쓸 수 있는 형태만 선언합니다. 독일어에는 목적어가 있는 형태가, 러시아어에는 장소가 있는 형태가 없습니다. 둘 다 명사의 어미가 바뀌는 격을 요구하는데 단어 풀은 형태를 하나씩만 담기 때문입니다. 어느 쪽도 답할 수 없는 요청은 그 언어가 가진 가장 가까운 형태로 처리되고, <code>language</code>를 지정하지 않으면 답할 수 있는 언어가 먼저 뽑힙니다.</p><p>둘째, 조사는 문장이 아니라 구에 붙습니다. 한국어는 앞말의 받침에 따라 <code>가</code>와 <code>이</code>를 고르므로 조사를 두 벌 저장하지 않아도 <code>사자가</code>와 <code>사슴이</code>가 제대로 나옵니다. 이탈리아어는 뒤따르는 명사의 첫소리에 따라 <code>l&#39;</code>, <code>lo</code>, <code>il</code>을 고릅니다. 독일어는 동사가 두 번째에 서므로 시간으로 시작하는 형태는 주어를 그 뒤에 놓습니다. <code>Am Morgen schläft ein Wolf.</code>처럼 씁니다.</p><h2 id="length-picks-the-shape" tabindex="-1">길이와 형태 선택 <a class="header-anchor" href="#length-picks-the-shape" aria-label="Permalink to &quot;길이와 형태 선택 {#length-picks-the-shape}&quot;">​</a></h2><p><code>minLength</code>와 <code>maxLength</code>는 문장 부호까지 포함한 문장 전체를 제한합니다. 범위 안에 들어올 수 없는 형태가 먼저 빠지고, 각 구는 뒤에 오는 구가 최소한의 자리를 확보하고 남은 만큼에서 뽑힙니다.</p><p>그래서 좁은 범위는 단어를 자르는 대신 수식어를 빼고, 넓은 범위는 수식어를 되돌립니다. 아무 제한 없이 그 언어가 만들 수 있는 범위는 <a href="./sentence-length-range"><code>sentenceLengthRange</code></a>가 알려 줍니다.</p><p><code>shape</code>는 같은 일을 더 큰 단위로 합니다. 글자 수가 아니라 구의 개수를 정하며, 짧은 문장과 긴 문장이라고 할 때 보통 뜻하는 쪽이 이것입니다.</p><h2 id="what-realism-changes" tabindex="-1"><code>realism</code>의 적용 범위 <a class="header-anchor" href="#what-realism-changes" aria-label="Permalink to &quot;`realism`의 적용 범위 {#what-realism-changes}&quot;">​</a></h2><p><code>realism</code>은 단어가 어디서 오는지만 정합니다. <code>&#39;invented&#39;</code>는 명사와 수식어를 그 언어의 소리로 지어내고, 그 주위의 문법은 그대로 둡니다. 조사도 관사도 일치도 형태도 모두 그 언어의 것입니다.</p><p>그래서 <code>수줍은 노오가 안개 파저멜을 챙긴다.</code>의 어휘는 한국어가 아니지만 문법은 한국어입니다.</p><h2 id="where-a-sentence-differs" tabindex="-1">닉네임과의 차이 <a class="header-anchor" href="#where-a-sentence-differs" aria-label="Permalink to &quot;닉네임과의 차이 {#where-a-sentence-differs}&quot;">​</a></h2><p><a href="./../nickname/rand-nickname"><code>randNickname</code></a>은 단어를 나란히 놓기만 하고, 문장은 그중 하나에 대해 무언가를 말합니다. 차이는 세 가지입니다.</p><ul><li>닉네임은 일부러 단어를 붙여 씁니다(<code>멋진사자</code>). 문장은 그 언어가 쓰는 대로 띄어 씁니다.</li><li>닉네임에는 동사가 없어 무엇과도 일치할 필요가 없습니다. 문장의 서술어는 일치해야 합니다.</li><li><code>randNickname</code>에는 <code>wordSeparator</code>가 있습니다. 닉네임은 사람이 직접 입력하는 문자열이기 때문입니다. 문장에는 없습니다. 띄어쓰기는 언어가 정합니다.</li></ul><p>두 생성기가 공유하는 것은 단어 풀뿐입니다.</p><h2 id="see-also" tabindex="-1">함께 보기 <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;함께 보기 {#see-also}&quot;">​</a></h2><ul><li><a href="./rand-sentence"><code>randSentence</code></a> — 모든 옵션의 설명.</li><li><a href="./sentence-length-range"><code>sentenceLengthRange</code></a> — 길이 옵션의 기본값이 되는 범위.</li><li><a href="./../nickname/">닉네임</a> — 같은 단어 풀을 쓰는 다른 생성 함수.</li></ul>',28)])])}const m=d(a,[["render",r]]);export{g as __pageData,m as default};
